function todayKey(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function persistMeta(){if(demo)return;try{localStorage.setItem('ultimo-tratto-notebook',JSON.stringify(meta))}catch(e){}}
function unlock(key){if(demo||tut||meta.badges[key])return;meta.badges[key]=todayKey();persistMeta();toast(t('Appunto conquistato: {0}',BADGES[key][0]));sfx('complete');if(typeof achCheck==='function')achCheck()}
function recordRun(win){if(tut)return;try{localStorage.removeItem('ultimo-tratto-run-v2')}catch(e){}if(recorded)return;recorded=true;let row={date:todayKey(),mode:gameMode,win,wave,score,kills,level:playerLevel,bossKills,seconds:Math.round(runStats.seconds||0),circles:barriers.length,kinds:[...new Set(towers.filter(t=>t.type).map(t=>t.type))],repairs:Math.round(runStats.repairs||0),perfect:perfectWaves};meta.recent.unshift(row);meta.recent=meta.recent.slice(0,12);if(gameMode==='daily')meta.daily[runDay]=Math.max(meta.daily[runDay]||0,score);persistMeta()}
let achTab=0,achFilter='all';
const ACH_TABS=[['Progresso',[0,4]],['Costruzione',[1,3]],['Combattimento',[2]],['Percorsi',[5]]];
function achAcc(a){let p=achPct(a),done=p>=100,v=achValue(a);return `<details class="ach-item${done?' done':''}"><summary><span>${done?'✓':'○'} ${a.n}</span><em>${done?'fatto':p+'%'}</em></summary><small>${a.d.replace('{0}',a.goal)}</small>${done?'':`<progress aria-label="Avanzamento" max="${a.goal}" value="${v}"></progress><small class="ach-pct">${Math.floor(v)}/${a.goal}</small>`}</details>`}
function achTabs(){return `<div class="lab-tabs ach-tabs" role="tablist">${ACH_TABS.map(([n],id)=>`<button role="tab" aria-selected="${id===achTab}" class="${id===achTab?'active':''}" onclick="achTab=${id};notebook()">${n}</button>`).join('')}</div>`}
let achOpen={};
function achFilters(counts){return `<div class="lab-tabs ach-tabs ach-filters" role="group" aria-label="Filtro">${[['all','Tutti'],['done','Completati'],['todo','Da completare']].map(([id,n])=>`<button aria-pressed="${id===achFilter}" class="${id===achFilter?'active':''}" onclick="achFilter='${id}';notebook()"><span>${n}</span><small>${counts[id]}</small></button>`).join('')}</div>`}
function achGroup(g,name,list,filterKey){let all=ACH.filter(a=>a.grp===g),nd=all.filter(a=>achPct(a)>=100).length,open=achOpen[g]!==undefined?achOpen[g]:(achFilter==='done'||nd<all.length);return `<details class="ach-group" data-g="${g}"${open?' open':''} ontoggle="achOpen[${g}]=this.open"><summary><span>${name}</span><em>${nd} / ${all.length}</em></summary>${list.map(achAcc).join('')}</details>`}
function notebook(){visitPanel('notebook',[]);achCheck(true);let [name,groups]=ACH_TABS[achTab]||ACH_TABS[0];let scope=ACH.filter(a=>groups.includes(a.grp));let isDone=a=>achPct(a)>=100;let counts={all:scope.length,done:scope.filter(isDone).length,todo:scope.filter(a=>!isDone(a)).length};let sel=scope.filter(a=>achFilter==='all'||(achFilter==='done')===isDone(a)).sort((a,b)=>isDone(a)-isDone(b)||achPct(b)-achPct(a));let body;if(!sel.length)body=`<p class="ach-empty">${achFilter==='done'?'Ancora nessun traguardo completato in questo gruppo.':'Hai completato tutti i traguardi di questo gruppo.'}</p>`;else body=groups.map(g=>{let list=sel.filter(a=>a.grp===g);return list.length?achGroup(g,ACH_GROUPS[g],list):''}).join('');show(`<div class="eyebrow">SU QUESTO DISPOSITIVO</div><div class="ach-head"><h2>Traguardi.</h2>${GC.available()?`<button class="icon gc-open" aria-label="Apri Game Center" onclick="GC.open()">${ICO.gamepad}</button>`:''}</div>${GC.available()?`<p class="gc-status" id="gcStatus" role="status">${GC.statusText()}</p>`:''}<p class="ach-count">${ACH.filter(isDone).length}/${ACH.length} completati · ${meta.starts} ${meta.starts===1?'partita':'partite'} · ${meta.days.length} ${meta.days.length===1?'giorno di gioco':'giorni di gioco'} · ★ Quaderno ${starTotal('campaign')}/24 · Sfida ${starTotal('daily')}/12 · Percorsi ${pathStarTotal()}/${MAPS.length*3}</p>${achTabs()}${achFilters(counts)}<div class="catalogue">${body}</div><button class="btn green" onclick="showMenu(started&&!over)">Torna al menu</button>`)}

const GC=(()=>{const g={prefix:'cs.',outbox:[],player:null,enabled:true,status:'disconnected'};window.GC=g;
 const bridge=()=>{try{return window.webkit?.messageHandlers?.gameCenter||null}catch(_){return null}};
 g.available=()=>!!bridge();
 g.send=m=>{if(!g.enabled)return;const msg={...m,version:1};g.outbox.push(msg);if(g.outbox.length>100)g.outbox.shift();try{bridge()?.postMessage(msg)}catch(_){}try{window.dispatchEvent(new CustomEvent('gamecenter',{detail:msg}))}catch(_){}};
 g.id=k=>g.prefix+k;
 g.achievement=(key,percent,banner)=>{if(Number.isFinite(percent))g.send({type:'achievement',id:g.id(key),percent:Math.max(0,Math.min(100,percent|0)),banner:!!banner})};
 g.score=(key,value)=>{if(Number.isFinite(value))g.send({type:'score',leaderboard:g.id(key),value:Math.max(0,Math.min(1000000000,Math.round(value)))})};
 const labels={disabled:'Game Center disattivato',connecting:'Accesso a Game Center…',connected:'Game Center connesso',error:'Game Center non disponibile. Riprova.',accountMismatch:'I progressi locali appartengono a un altro account.',pending:'Sincronizzazione in attesa',disconnected:'Game Center non connesso'};
 g.statusText=()=>tr(labels[g.enabled?g.status:'disabled']||labels.disconnected);
 g.refresh=()=>{try{const el=document.getElementById('gcStatus');if(el)el.textContent=g.statusText()}catch(_){}};
 g.receipt=data=>{if(!data||!['achievement','score'].includes(data.kind)||typeof data.id!=='string'||!Number.isFinite(data.value))return;g.lastReceipt={kind:data.kind,id:data.id,value:data.value};try{window.dispatchEvent(new CustomEvent('gamecenter:receipt',{detail:g.lastReceipt}))}catch(_){}};
 g.nativeStatus=data=>{if(!data||typeof data.state!=='string')return;g.status=data.state;g.refresh()};
 g.authenticated=(alias,account)=>{if(!g.enabled)return;g.player=alias||true;g.account=account||null;g.status='connected';g.refresh();if(g.onSync)g.onSync()};
 g.setEnabled=on=>{on=!!on;if(on===g.enabled)return;g.enabled=on;if(on){g.status='connecting';g.send({type:'ready'});if(g.onSync)g.onSync()}else{g.player=null;g.status='disabled';try{bridge()?.postMessage({type:'disable',version:1})}catch(_){}}g.refresh()};
 g.open=()=>{if(!g.available())return;if(!g.enabled){visitPanel('gameCenter',[]);show(`<p>${tr('Game Center disattivato')}</p><button class="btn green" onclick="setPref('gc',true,true);backPanel();GC.open()">${tr('Attiva Game Center')}</button><button class="btn light" onclick="backPanel()">${tr('Annulla')}</button>`);return}g.send({type:'showGameCenter'})};
 return g})();
