function statObj(){if(!meta.stat||typeof meta.stat!=='object'||Array.isArray(meta.stat))meta.stat={};return meta.stat}
function statAdd(k,n=1){if(demo||tut)return;let st=statObj();st[k]=(Number.isFinite(st[k])&&st[k]>0?st[k]:0)+n}
function statMax(k,v){if(demo||tut)return;let st=statObj();if(!(st[k]>=v))st[k]=v}
function statGet(k){let v=meta.stat&&typeof meta.stat==='object'?meta.stat[k]:0;return Number.isFinite(v)&&v>0?v:0}
function achValue(a){let v=+a.cur();return Number.isFinite(v)?Math.max(0,Math.min(a.goal,v)):0}
function achPct(a){return Math.floor(100*achValue(a)/a.goal)}
let achSent={};
function gcScores(){if(tut)return;GC.score('best_score',best);GC.score('best_wave',statGet('bestWave'));GC.score('total_stars',starTotal('campaign'))}
function achCheck(silent){if(demo||tut)return 0;if(!meta.ach||typeof meta.ach!=='object'||Array.isArray(meta.ach))meta.ach={};let fresh=[];for(let a of ACH){let p=achPct(a);if(p>(achSent[a.k]||0)){achSent[a.k]=p;GC.achievement(a.k,p,false);if(p>=100&&!meta.ach[a.k]){meta.ach[a.k]=todayKey();if(!silent&&!a.quiet)fresh.push(a)}}}if(fresh.length){persistMeta();toast(fresh.length===1?t('Traguardo: {0}',fresh[0].n):t('Traguardi: {0}',fresh.map(a=>tr(a.n)).join(', ')));sfx('complete')}return fresh.length}
