const STUDIES={damage:{name:'Leghe di grafite',icon:'△',desc:'Aumenta il danno di tutte le difese.'},regen:{name:'Riciclo delle briciole',icon:'✎',desc:'Migliora la rigenerazione di grafite.'},repair:{name:'Fibre del foglio',icon:'◌',desc:'Rende più efficaci le riparazioni.'}};
let studies={damage:0,regen:0,repair:0};
function studyOffer(key){let n=studies[key]||0;return {cost:Math.min(110,28+n*9),time:Math.min(90,18+n*6),gain:(key==='damage'?.08:key==='regen'?.3:.15)/(1+n*.25)}}
function jobName(j=researchJob){if(!j)return '';if(j.kind==='care')return PAPER_CURES[j.key]?.name||'Trattamento';if(j.kind==='project')return PERKS[j.key]?.name||'Progetto';if(j.kind==='study')return STUDIES[j.key]?.name||'Studio';if(j.kind==='lab')return 'Ampliamento del Laboratorio';if(j.kind==='branch')return SPECIALIZATIONS[j.towerType]?.[j.key]?.name||'Specializzazione';return TECHNOLOGIES[j.key]?.name||'Ricerca'}
function validJob(j){return !!j&&Number.isFinite(j.remaining)&&Number.isFinite(j.total)&&j.total>0&&j.remaining>0&&(j.kind==='care'&&PAPER_CURES[j.key]||j.kind==='lab'||j.kind==='project'&&PERKS[j.key]||j.kind==='study'&&STUDIES[j.key]||j.kind==='branch'&&SPECIALIZATIONS[j.towerType]?.[j.key]&&Number.isInteger(j.tower)||(!j.kind||j.kind==='tech')&&TECHNOLOGIES[j.key])}
function beginJob(job,cost,time){if(!hasLab()||researchJob||ink<cost||over)return false;ink-=cost;researchJob={...job,cost,remaining:time,total:time};hide();selected=-1;dock();ui();saveRun();toast(jobName()+' · ricerca avviata, '+time+'s di assalto.');return true}
function startStudy(key){if(!STUDIES[key])return false;let o=studyOffer(key);return beginJob({kind:'study',key},o.cost,o.time)}
let pendingAlly=null;
const ALLIES={pink:{name:"Gommina larga",cost:24,desc:"Cancella un settore largo."},fast:{name:"Punta rapida",cost:28,desc:"Raggiunge in fretta il contorno."},armored:{name:"Gomma corazzata",cost:42,desc:"Resiste ai colpi delle torri."},splitter:{name:"Gomma pane",cost:48,desc:"Si divide in briciole quando viene distrutta."}};
let avatarId=0,avatarTarget=null,reverseTier=1,reverseRage=0,reverseCooldown=0,reverseElapsed=0,reverseGoal=35,fortressInk=160,repairClock=0,erosionXP=0;
