function clearTower(t){t.type=null;t.level=1;t.hp=0;t.maxhp=0;t.destroyed=false;t.branch=null;t.priority='first';t.cooldown=0;t.damageFlash=0}
function defenseOpacity(t){ensureTowerHealth(t);return t.type?.25+.75*t.hp/t.maxhp:1}

function towerMaxHP(t){return Math.round((gameMode==='paths'?PATH_TUNE.hpTower*(paperProfile().tower||1):1)*(({triangle:110,spiral:100,mortar:140,sniper:95,mender:120,pentagon:115,star:105,octagon:175,lab:180}[t.type]||0)+Math.max(0,(t.level||1)-1)*45))}
function ensureTowerHealth(t){if(!t?.type)return;let max=towerMaxHP(t);if(!Number.isFinite(t.hp))t.hp=max;else if(Number.isFinite(t.maxhp)&&t.maxhp!==max&&!t.destroyed)t.hp+=max-t.maxhp;t.maxhp=max;t.hp=Math.max(0,Math.min(max,t.hp));if(t.hp<=0)t.destroyed=true;else t.destroyed=!!t.destroyed}
function towerOperational(t){if(!t?.type)return false;ensureTowerHealth(t);return t.hp>0&&!t.destroyed}
function towerRepairCost(t){ensureTowerHealth(t);return Math.ceil(Math.max(0,t.maxhp-t.hp)*.24*paperProfile().repair*(gameMode==='paths'?PATH_TUNE.repair:1))}
function towerRepairButton(i){let t=towers[i];if(!t?.type)return '';ensureTowerHealth(t);let cost=towerRepairCost(t);return `<div class="tower-integrity"><b>Integrità ${Math.ceil(t.hp)} / ${t.maxhp}${t.destroyed?' · ABBATTUTA':''}</b><progress aria-label="Integrità della difesa" max="${t.maxhp}" value="${t.hp}"></progress></div>${cost?`<button class="btn ${t.destroyed?'green':'light'}" ${ink<cost?'disabled':''} onclick="repairTower(${i})">Ripara · ${cost}✎</button>${ink<cost?'<span class="lock-reason">Grafite insufficiente</span>':''}`:'<p>Difesa integra</p>'}`}

function damagedDefenses(){return towers.map((t,i)=>({t,i})).filter(({t})=>t?.type&&(ensureTowerHealth(t),t.hp<t.maxhp)).sort((a,b)=>a.t.hp/a.t.maxhp-b.t.hp/b.t.maxhp)}
function repairAllCost(){return damagedDefenses().reduce((a,{t})=>a+towerRepairCost(t),0)}
function repairAll(){if(gameMode==='paths'&&phase==='wave'){toast('Si ripara solo tra un’ondata e l’altra.');return}if(gameMode==='erasers'||!started||over)return 0;let fixed=0,spent=0,left=0;for(let {t,i} of damagedDefenses()){let cost=towerRepairCost(t);if(!cost)continue;if(ink<cost){left++;continue}ink-=cost;spent+=cost;t.hp=t.maxhp;t.destroyed=false;t.damageFlash=0;upgradeFx(i);fixed++}if(!fixed){toast(left?'Serve più grafite.':'Tutte le difese sono integre.');return 0}statAdd('heals',fixed);statAdd('healAll');achCheck();saveRun();ui();sfx('repair');toast(fixed===1?'1 difesa ripristinata · '+spent+'✎':fixed+' difese ripristinate · '+spent+'✎'+(left?' · '+left+' da curare con più grafite':''));if(panelCurrent?.name==='tower')towerDetails();else if(panelCurrent?.name==='lab')labMenu('maintenance','defenses');return fixed}
function repairAllButton(){let n=damagedDefenses().length;if(n<2||gameMode==='erasers')return '';let cost=repairAllCost();return `<button class="btn green" ${ink<1?'disabled':''} onclick="repairAll()">Cura tutto · ${cost}✎<small> ${n} difese</small></button>`+(ink<cost?'<span class="lock-reason">Grafite insufficiente per tutte: curo prima le più danneggiate.</span>':'')}
function repairTower(i,quiet){let t=towers[i];if(gameMode==='erasers'||!started||over||!t?.type)return false;if(gameMode==='paths'&&phase==='wave'){toast('Si ripara solo tra un’ondata e l’altra.');return false}ensureTowerHealth(t);let cost=towerRepairCost(t);if(!cost||ink<cost){toast(cost?'Serve più grafite.':'Difesa già integra.');return false}ink-=cost;t.hp=t.maxhp;t.destroyed=false;t.damageFlash=0;upgradeFx(i);selected=i;statAdd('heals');achCheck();saveRun();ui();sfx('repair');toast(t.type==='lab'?'Laboratorio ripristinato. Le ricerche possono riprendere.':'Difesa ripristinata.');if(!quiet)towerDetails();return true}
function damageTower(i,amount){let t=towers[i];if(!towerOperational(t)||amount<=0)return;let was=t.hp;t.hp=Math.max(0,t.hp-amount*(sealTime>0?.55:1));let dealt=was-t.hp;t.damageFlash=1;sfx('hit');if(t.hp<=0){let p=slot(i),type=t.type,color=DEFENSES[type].color;addFx('eraseBurst',{x:p.x,y:p.y,radius:48,color,life:.85,shape:type});burst(p.x,p.y,color,16);if(researchJob?.kind==='branch'&&researchJob.tower===i){let refund=Math.floor((researchJob.cost||48)*Math.max(0,researchJob.remaining)/researchJob.total);ink=Math.min(MAXINK,ink+refund);researchJob=null;toast('Specializzazione interrotta · recuperati '+refund+'✎')}clearTower(t);if(selected===i)selected=-1;if(gameMode==='erasers'){score+=45;ink=Math.min(MAXINK,ink+8);toast(tt('{0} cancellato!',DEFENSES[type].name))}else toast(type==='lab'?'Laboratorio cancellato. Costruiscine uno per riprendere la ricerca.':tt('{0} cancellato · postazione libera.',DEFENSES[type].name));sfx('breach');saveRun()}return dealt}
function towerPathOpen(e,p){let x=CX+Math.cos(e.a)*e.r,y=CY+Math.sin(e.a)*e.r,dx=p.x-x,dy=p.y-y,A=dx*dx+dy*dy;if(A<1)return true;for(let b of barriers){let ox=x-CX,oy=y-CY,B=2*(ox*dx+oy*dy),C=ox*ox+oy*oy-b.r*b.r,D=B*B-4*A*C;if(D<0)continue;for(let u of [(-B-Math.sqrt(D))/(2*A),(-B+Math.sqrt(D))/(2*A)])if(u>.001&&u<.999&&b.hp[index(Math.atan2(y+dy*u-CY,x+dx*u-CX))]>=7)return false}return true}
function engageTower(e,dt,controlled=false){if(e.dead||e.stun>0)return false;let p={x:CX+Math.cos(e.a)*e.r,y:CY+Math.sin(e.a)*e.r},target=-1,distance=controlled?32:125;for(let i=0;i<towers.length;i++){if(!towerOperational(towers[i]))continue;let q=slot(i),d=dist(p,q);if(d<distance&&towerPathOpen(e,q)){distance=d;target=i}}if(target<0)return false;let q=slot(target);if(distance>27&&!controlled){let step=Math.min(distance-26,e.speed*(e.slow>0?.42:1)*dt),x=p.x+(q.x-p.x)/distance*step,y=p.y+(q.y-p.y)/distance*step;e.a=norm(Math.atan2(y-CY,x-CX));e.r=Math.hypot(x-CX,y-CY)}else{damageTower(target,e.damage*.8*dt*(e.avatar&&reverseRage>0?1.7:1));e.towerSwing=(e.towerSwing||0)+dt;if(e.towerSwing>.24){e.towerSwing=0;addFx('cut',{x:q.x,y:q.y,angle:e.a,radius:16,color:'#bd8e87',life:.22})}}return true}
function damageTowersNear(p,r,amount){for(let i=0;i<towers.length;i++)if(towerOperational(towers[i])&&dist(p,slot(i))<r)damageTower(i,amount)}
function drawTowerCondition(i){let t=towers[i];ensureTowerHealth(t);if(!t.type||t.hp>=t.maxhp&&selected!==i)return;let health=t.hp/t.maxhp;rr(-18,30,36,3,1,'#d8d2c2');rr(-18,30,36*health,3,1,health<.35?'#bd8177':'#719e88')}

let panelCurrent=null,panelHistory=[],panelRestoring=false;
function visitPanel(name,args=[]){try{MUSIC.cancelJingle()}catch(_){}let route={name,args};if(panelRestoring){panelRestoring=false;panelCurrent=route;return}if(name==='intro'||name==='menu'){panelHistory=[];panelCurrent=route;return}if(panelCurrent&&panelCurrent.name!==name)panelHistory.push(panelCurrent);panelCurrent=route}
function backPanel(){let route=panelHistory.pop();if(!route){if(started&&!over)showMenu(true);else intro();return}panelRestoring=true;const render={credits:()=>credits(),intro:()=>intro(),labHelp:()=>labAccess(),menu:()=>showMenu(...route.args),lab:()=>labMenu(...route.args),guide:()=>guide(),appearance:()=>showAppearance(...route.args),powers:()=>powerMenu(),tools:()=>openRepairTools(),tower:()=>{selected=route.args[0];towerDetails()},catalogue:()=>{selected=route.args[0];catalogue()},branches:()=>{selected=route.args[0];showSpecializations()},notebook:()=>notebook(),gommario:()=>gommario(),forecast:()=>showForecast(),paper:()=>choosePaper(),restart:()=>confirmRestart(),allies:()=>attackShop(),reverseGuide:()=>reverseGuide(),language:()=>languageMenu(),maps:()=>mapMenu(),settings:()=>settingsMenu(...route.args),reset:()=>confirmReset()};if(render[route.name])render[route.name]();else{panelRestoring=false;showMenu(started&&!over)}}
function activePanelGame(){return started&&!over}
function goHome(){if(started&&!over)saveRun();panelHistory=[];intro()}
function closePanel(){if(started&&!over)resume();else intro()}

// Grab bar: drag down to close the panel, release early to stay open.
let gripDrag=null;
document.addEventListener('pointerdown',e=>{if(!e.target.closest||!e.target.closest('.panel-grip'))return;gripDrag={id:e.pointerId,y:e.clientY,dy:0};$('dialog').style.transition='none'},{passive:true});
document.addEventListener('pointermove',e=>{if(!gripDrag||e.pointerId!==gripDrag.id)return;gripDrag.dy=Math.max(0,e.clientY-gripDrag.y);$('dialog').style.transform='translateY('+gripDrag.dy+'px)';$('dialog').style.opacity=String(Math.max(.35,1-gripDrag.dy/420))},{passive:true});
function endGripDrag(e){if(!gripDrag||(e&&e.pointerId!==gripDrag.id))return;let dy=gripDrag.dy,d=$('dialog');gripDrag=null;d.style.transition='transform .18s ease,opacity .18s ease';if(dy>90){d.style.transform='translateY(100%)';d.style.opacity='0';setTimeout(()=>{d.style.transition='';d.style.transform='';d.style.opacity='';closePanel()},180)}else{d.style.transform='';d.style.opacity='';setTimeout(()=>{d.style.transition=''},200)}}
document.addEventListener('pointerup',endGripDrag,{passive:true});
document.addEventListener('pointercancel',endGripDrag,{passive:true});

function blockReason(cost=0,{done=false,level=1,requires=[]}={}){if(done)return 'Completato';if(playerLevel<level)return 'Richiede livello '+level;let missing=requires.filter(k=>!tech[k]);if(missing.length)return t('Prima: {0}',missing.map(k=>tr(TECHNOLOGIES[k].name)).join(', '));if(!hasLab())return labIndex()>=0?'Laboratorio abbattuto':'Costruisci il Laboratorio';if(researchJob)return 'Banco occupato';if(ink<cost)return 'Grafite insufficiente';return ''}

function figureIcon(type,size=56){let d=DEFENSES[type];if(!d)return '';let body={triangle:'<path d="M49 29L14 10L14 48Z"/>',mortar:'<path d="M43 9L54 29L43 49H19L8 29L19 9Z"/><path d="M29 26H52V33H29Z"/>',sniper:'<path d="M3 29L31 13L59 29L31 45Z"/><path d="M26 29H61" fill="none" stroke="#fff9e9" stroke-width="2.6"/>',mender:'<rect x="10" y="8" width="42" height="42" rx="5"/><path d="M31 18V40M20 29H42" fill="none" stroke="#fff9e9" stroke-width="4"/>',pentagon:'<path d="M31 5L55 23L46 51H16L7 23Z"/><path d="M34 14L24 31H34L27 44" fill="none" stroke="#fff9e9" stroke-width="3"/>',star:'<path d="M31 3L38 21L58 22L43 35L48 55L31 44L14 55L19 35L4 22L24 21Z"/>',octagon:'<path d="M21 5H42L56 19V39L42 53H21L7 39V19Z"/><circle cx="31" cy="29" r="12" fill="none" stroke="#fff9e9" stroke-width="3"/>',lab:'<rect x="7" y="9" width="48" height="40" rx="4"/><path d="M31 10V49M13 20H24M13 27H23M38 20H48M38 27H48" fill="none"/>',spiral:'<circle cx="31" cy="29" r="24"/><path d="M32 29C38 20 23 16 21 27C17 42 44 47 47 29C51 7 13 3 10 26C7 47 25 55 40 50" fill="none" stroke="#fff9e9" stroke-width="2.8"/>'}[type]||'';return `<svg class="figure-icon" width="${size}" height="${size}" viewBox="0 0 62 60" aria-hidden="true" focusable="false"><g fill="none" stroke="#7e9e9166" stroke-width=".8"><circle cx="31" cy="29" r="27" stroke-dasharray="2 3"/><path d="M1 29H61M31 0V59" stroke-dasharray="3 3"/></g><g fill="${d.color}" stroke="${mixInk(d.color,'#283d37',.45)}" stroke-width="1.8" stroke-linejoin="round">${body}</g>${['lab','spiral'].includes(type)?'':`<g fill="none" stroke="#fffaf0" stroke-width="1.1" stroke-linejoin="round" opacity=".6" transform="translate(31 29) scale(.58) translate(-31 -29)">${body}</g>`}<path d="M16 15L23 11" stroke="#fffaf0" stroke-width="2.3" stroke-linecap="round" opacity=".7"/></svg>`}

const GLYPH={needle:'<path d="M5 19L19 5"/><path d="M15.5 4.5l4 4"/><path d="M6 18c2-3 4-1 5-3s-1-4 1-5" stroke-dasharray="1.5 2.5"/>',circles:'<circle cx="12" cy="12" r="3"/><circle cx="12" cy="12" r="6.5"/><circle cx="12" cy="12" r="10" stroke-dasharray="2 3"/>',wind:'<path d="M3 9h11a3 3 0 1 0-3-3"/><path d="M3 14h15a3 3 0 1 1-3 3"/><path d="M3 19h6"/>',shield:'<path d="M12 3l7 3v5c0 5-3 8-7 10-4-2-7-5-7-10V6z"/>',snow:'<path d="M12 3v18M4.5 7.5l15 9M19.5 7.5l-15 9"/><path d="M9.5 4.5L12 7l2.5-2.5M9.5 19.5L12 17l2.5 2.5"/>',storm:'<path d="M7 15a4 4 0 0 1 .5-8 5 5 0 0 1 9.500 1.500A3.500 3.500 0 0 1 17 15z"/><path d="M12 13l-2 4h3l-2 4"/>',evo:'<path d="M12 20V6"/><path d="M6 12l6-7 6 7"/><path d="M8 20h8"/>',drop:'<path d="M12 3c4 5 6 7.500 6 11a6 6 0 0 1-12 0c0-3.500 2-6 6-11z"/><path d="M9.500 14.500a3 3 0 0 0 2.500 2.500"/>',bulb:'<path d="M9 18h6M10 21h4"/><path d="M12 3a6 6 0 0 0-3.500 10.900c.6.5 1 1.200 1 2.100h5c0-.9.4-1.600 1-2.100A6 6 0 0 0 12 3z"/>',pencil:'<path d="M4 20l1-4L16 5a2.100 2.100 0 0 1 3 3L8 19z"/><path d="M14 7l3 3"/>'};
function cardGlyph(name='',desc=''){let n=(name+' '+desc).toLowerCase(),k=/cucit|toppa|cuci/.test(n)?'needle':/cerchi|contorno|espansione/.test(n)?'circles':/tempesta/.test(n)?'storm':/stasi/.test(n)?'snow':/sigillo/.test(n)?'shield':/aria|soffio|dinamica/.test(n)?'wind':/evoluzion|special/.test(n)?'evo':/sbianc|restaur|trattament|cura|carta|usura/.test(n)?'drop':/progett|studi|ricerca|manutenz/.test(n)?'bulb':'pencil';return `<svg viewBox="0 0 24 24" aria-hidden="true">${GLYPH[k]}</svg>`}
function labCard({name,desc,cost,time,action,reason='',icon='',figure=null}){return `<button class="choice illustrated-card" ${reason?'disabled':''} onclick="${action}"><span class="card-art">${figure?figureIcon(figure):`<span class="command-symbol">${!icon||icon==='⌁'?cardGlyph(name,desc):icon}</span>`}</span><span class="card-copy"><b>${name}</b><small>${desc}</small><span class="card-meta">${cost}✎${time?' · '+time+'s':''}</span>${reason?`<span class="lock-reason">${reason}</span>`:''}</span></button>`}
function labAccess(){if(!started||over){toast('Inizia una partita per costruire il Laboratorio.');return}if(labIndex()>=0&&!hasLab()){selected=labIndex();toast('Laboratorio abbattuto: riparalo per riprendere la ricerca.');towerDetails();return}if(labIndex()<0){visitPanel('labHelp');show('<div class="eyebrow">LABORATORIO</div><h2>Un posto per le idee.</h2><p>Costruiscilo su una postazione + per 45 grafite. Ricerca difese, cura il foglio e acquista cariche.</p><button class="btn green" onclick="resume()">Torna al foglio</button>');return}labMenu()}

function labIndex(){return towers.findIndex(t=>t.type==='lab')}
function hasLab(){return labIndex()>=0&&towerOperational(towers[labIndex()])}
function researchReady(key){let t=TECHNOLOGIES[key];return !!t&&hasLab()&&!researchJob&&!tech[key]&&playerLevel>=t.level&&t.requires.every(k=>tech[k])&&ink>=t.cost}
let labCategory='discoveries',maintenanceCategory='paper';
function labMenu(tab=null,category=null){if(!tab&&labCategory==='discoveries'&&techEntries().every(([k])=>tech[k]))labCategory='studies';let old=tab;tab=({perks:'research',studies:'research',care:'maintenance',powers:'charges'})[tab]||tab||'research';if(old==='perks')category='projects';if(old==='studies')category='studies';if(tab==='research'&&category)labCategory=category;if(tab==='maintenance'&&category)maintenanceCategory=category;if(gameMode==='erasers'){attackShop();return}if(!hasLab()){labAccess();return}visitPanel('lab',[tab,tab==='research'?labCategory:maintenanceCategory]);let level=towers[labIndex()].level,busy=!!researchJob;let status=busy?`<div class="research-status"><b>⌁ ${jobName()}</b><span>${Math.ceil(researchJob.remaining/(1+(level-1)*.35))}s d’assalto · ricerca in pausa nel menu</span><progress aria-label="Avanzamento ricerca" max="${researchJob.total}" value="${researchJob.total-researchJob.remaining}"></progress></div>`:'<div class="bench-idle">Banco libero · una ricerca alla volta</div>';let header=`<div class="lab-heading"><h2>Laboratorio</h2><span>Liv. ${level} · ${Math.floor(ink)}✎</span></div><div class="lab-chips" role="tablist" aria-label="Sezioni del Laboratorio">${LAB_CHIPS.map(([t,c,label])=>{let on=tab===t&&(c===null||(t==='research'?labCategory:maintenanceCategory)===c);return `<button role="tab" aria-selected="${on}" aria-pressed="${on}" onclick="labMenu('${t}'${c?`,'${c}'`:''})">${label}</button>`}).join('')}</div>`;header+=status;let content='';if(tab==='research'&&labCategory==='discoveries'){let pending=techEntries().filter(([k])=>!tech[k]).sort((a,b)=>(blockReason(a[1].cost,a[1])?1:0)-(blockReason(b[1].cost,b[1])?1:0)||(LAB_ORDER.indexOf(a[0])+100)%100-(LAB_ORDER.indexOf(b[0])+100)%100),completed=techEntries().filter(([k])=>tech[k]);content=pending.map(([key,t])=>labCard({name:t.name,figure:DEFENSES[key]?key:null,desc:t.unlock,cost:t.cost,time:t.time,action:`startResearch('${key}')`,reason:blockReason(t.cost,t)})).join('')||'<p class="empty-state">Tutte le scoperte completate. Continua con Progetti o Studi.</p>';if(level<3)content+=labCard({name:'Amplia il Laboratorio',figure:'lab',desc:'Le ricerche procedono più velocemente.',cost:40,time:18+level*6,action:'upgradeLab()',reason:blockReason(40)});if(completed.length)content+=`<details class="completed-list"><summary>Completate · ${completed.length}/${techEntries().length}</summary><p>${completed.map(([k,t])=>'✓ '+t.name).join('<br>')}</p></details>`}if(tab==='research'&&labCategory==='projects')content=Object.entries(PERKS).map(([key,t])=>{let n=perkHistory.filter(k=>k===key).length,max=key==='circle'?2:3;return labCard({name:t.name,icon:t.icon,desc:t.desc+' · '+n+'/'+max,cost:22+n*12,time:12+n*6,action:`buyProject('${key}')`,reason:blockReason(22+n*12,{done:n>=max})})}).join('');if(tab==='research'&&labCategory==='studies')content='<p class="panel-note">Ripetibili: costo crescente e benefici via via minori.</p>'+Object.entries(STUDIES).map(([key,t])=>{let o=studyOffer(key),bonus=key==='regen'?'+'+o.gain.toFixed(2)+'✎/s':'+'+(o.gain*100).toFixed(1)+'%';return labCard({name:t.name,icon:t.icon,desc:bonus+' · ciclo '+((studies[key]||0)+1),cost:o.cost,time:o.time,action:`startStudy('${key}')`,reason:blockReason(o.cost)})}).join('');if(tab==='charges')content='<p class="panel-note">Cariche pronte dopo la ricerca · massimo tre per tipo.</p>'+Object.entries(POWERS).map(([key,t])=>labCard({name:t.name+' ×'+powerCharges[key],icon:t.icon,desc:t.desc,cost:t.cost,action:`buyPowerCharge('${key}')`,reason:!tech[key]?'Ricerca: '+TECHNOLOGIES[key].name:powerCharges[key]>=3?'Scorta completa':ink<t.cost?'Grafite insufficiente':''})).join('');if(tab==='maintenance'&&maintenanceCategory==='paper')content=paperCareContent(busy);if(tab==='maintenance'&&maintenanceCategory==='defenses'){let damaged=towers.map((t,i)=>({t,i})).filter(({t})=>t.type&&(ensureTowerHealth(t),t.hp<t.maxhp));content=repairAllButton()+damaged.map(({t,i})=>labCard({name:DEFENSES[t.type].name+' · posto '+(i+1),figure:t.type,desc:Math.ceil(t.hp)+'/'+t.maxhp+' integrità · ripara prima che venga cancellata',cost:towerRepairCost(t),action:`repairTower(${i})`,reason:ink<towerRepairCost(t)?'Grafite insufficiente':''})).join('')||'<p class="empty-state">Tutte le difese sono integre.</p>'}show(content,header)}

function startResearch(key){if(!researchReady(key))return false;let t=TECHNOLOGIES[key];return beginJob({kind:'tech',key},t.cost,t.time)}
function updateResearch(dt){if(!researchJob||!hasLab()||phase!=='wave'||paused||over)return;researchJob.remaining-=dt*(1+(towers[labIndex()].level-1)*.35);if(researchJob.remaining>0)return;let j=researchJob,name=jobName(j);researchJob=null;if(j.kind==='care'){let cure=PAPER_CURES[j.key];paperWear=Math.max(0,paperWear-cure.restore);paperProtection=Math.max(paperProtection,cure.protection||0);addFx('mend',{x:CX,y:CY,radius:R,color:'#81b6ad',life:1})}else if(j.kind==='project')applyProject(j.key);else if(j.kind==='study'){let o=studyOffer(j.key);if(j.key==='damage')damageMult+=o.gain;if(j.key==='regen')regen+=o.gain;if(j.key==='repair')repairMult+=o.gain;studies[j.key]=(studies[j.key]||0)+1}else if(j.kind==='lab')towers[labIndex()].level=Math.min(3,towers[labIndex()].level+1);else if(j.kind==='branch'){let t=towers[j.tower];if(t?.type===j.towerType&&t.level===2){t.branch=j.key;t.level=3;t.cooldown=0;upgradeFx(j.tower);statAdd('specs')}}else{tech[j.key]=true;if(POWERS[j.key])unseenPower=true}statAdd('research');achCheck();toast(t('Completato: {0}',name));sfx('complete');dock();ui();saveRun()}
function upgradeLab(){if(!hasLab()||towers[labIndex()].level>=3)return false;return beginJob({kind:'lab'},40,18+towers[labIndex()].level*6)}
function buyPowerCharge(key){if(!hasLab()||!tech[key]||!POWERS[key]||ink<POWERS[key].cost||powerCharges[key]>=3)return false;ink-=POWERS[key].cost;powerCharges[key]++;selectedPower=key;labMenu('powers');ui();return true}
function buyProject(key){if(!PERKS[key])return false;let n=perkHistory.filter(k=>k===key).length;if(n>=(key==='circle'?2:3))return false;return beginJob({kind:'project',key},22+n*12,12+n*6)}
function applyProject(kind){if(kind==='regen')regen+=.6;if(kind==='damage')damageMult+=.18;if(kind==='repair'){repairMult+=.25;core=Math.min(100,core+20)}if(kind==='economy')buildDiscount=Math.min(.4,buildDiscount+.15);if(kind==='range')rangeBonus+=25;if(kind==='circle')circleDiscount=Math.min(.4,circleDiscount+.2);perkHistory.push(kind)}
