function isBoss(e){return ['roller','setSquare','boss'].includes(e.type)}
function xpThreshold(level=playerLevel){return 55+(level-1)*18}
function gainXP(amount){playerXP+=amount;let leveled=false;while(playerLevel<20&&playerXP>=xpThreshold()){playerXP-=xpThreshold();playerLevel++;leveled=true;ink=Math.min(MAXINK,ink+8);toast('Livello '+playerLevel+(gameMode==='erasers'?' · continua a cancellare!':' · nuovi progetti disponibili nel Laboratorio'));addFx('level',{x:CX,y:CY,radius:70,color:'#c2ac69',life:1.1,level:playerLevel});sfx('complete')}if(leveled){dock();ui()}}
