 m.sockets=m.sockets.map(p=>{let q=f(p),best=1e9,bx=0,by=0;for(let P of m.paths)for(let i=1;i<P.length;i++){let ax=P[i-1][0],ay=P[i-1][1],dx=P[i][0]-ax,dy=P[i][1]-ay,u=Math.max(0,Math.min(1,((q[0]-ax)*dx+(q[1]-ay)*dy)/(dx*dx+dy*dy||1))),x=ax+dx*u,y=ay+dy*u,d=Math.hypot(q[0]-x,q[1]-y);if(d<best){best=d;bx=x;by=y}}
  let nx=best>.01?(q[0]-bx)/best:0,ny=best>.01?(q[1]-by)/best:1;return[Math.round(bx+nx*SOCKET_OFF),Math.round(by+ny*SOCKET_OFF)]});
 let xs=m.paths.flat().map(p=>p[0]).concat(m.sockets.map(p=>p[0])),ys=m.paths.flat().map(p=>p[1]).concat(m.sockets.map(p=>p[1]));
 m.bounds={x0:Math.min(...xs)-140,x1:Math.max(...xs)+140,y0:Math.min(...ys)-140,y1:Math.max(...ys)+140};
