function hapticAvailable(){try{return !!hapticBridge()||(typeof navigator!=='undefined'&&typeof navigator.vibrate==='function')}catch(_){return false}}
function hapticFor(type){let kind=HAPTIC_KIND[type]||(HAPTIC_VIBE[type]?type:null);if(!kind||!prefs.haptic||document.hidden)return;let now=performance.now();if(now-lastBuzz<(HAPTIC_GAP[type]||90))return;lastBuzz=now;hapticLog.push(kind);if(hapticLog.length>50)hapticLog.shift();let b=hapticBridge();if(b){try{b.postMessage({kind,version:1});return}catch(_){}}if(typeof navigator!=='undefined'&&typeof navigator.vibrate==='function'){try{navigator.vibrate(HAPTIC_VIBE[kind])}catch(_){}}}
function setPref(key,val,quiet){prefs[key]=val;savePrefs();applyPrefs();if(key==='sound'&&val){try{audioUnlock();sfx('tap')}catch(e){soundOn=false;prefs.sound=false;savePrefs()}}if(['music','musicVol','sound','volume'].includes(key)){syncSfxLevel();try{if(prefs.music||prefs.sound)audioUnlock();MUSIC.tick();if(!prefs.sound)silenceScrape();if(!prefs.music&&!prefs.sound&&actx)actx.suspend().catch(()=>{})}catch(_){}}if(key==='haptic'&&val)hapticFor('tap');if(key==='gc')GC.setEnabled(val);if(!quiet)settingsMenu(activePanelGame())}
function prefSwitch(key,title,desc){return `<button class="set-row" role="switch" aria-checked="${!!prefs[key]}" onclick="setPref('${key}',${!prefs[key]})"><span><b>${title}</b><small>${desc}</small></span><span class="switch ${prefs[key]?'on':''}" aria-hidden="true"><i></i></span></button>`}
function prefSeg(key,title,opts){return `<div class="set-row col"><span><b>${title}</b></span><div class="seg" role="group" aria-label="${title}">${opts.map(([v,l])=>`<button aria-pressed="${prefs[key]===v}" onclick="setPref('${key}',${typeof v==='string'?`'${v}'`:v})">${l}</button>`).join('')}</div></div>`}
function confirmReset(){visitPanel('reset',[]);show(`<p>Verranno cancellati salvataggi, traguardi e impostazioni su questo dispositivo. L’operazione non si può annullare.</p><button class="btn danger" onclick="resetAllData()">Sì, cancella tutto</button><button class="btn light" onclick="backPanel()">Annulla</button>`)}
function resetAllData(){try{window.webkit?.messageHandlers?.gameCenter?.postMessage({type:'clearLocalProgress',version:1})}catch(_){}try{Object.keys(localStorage).filter(k=>k.startsWith('ultimo-tratto-')).forEach(k=>localStorage.removeItem(k))}catch(e){}location.reload()}
function openA11y(){try{let ov=$('overlay'),dl=$('dialog');ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');ov.setAttribute('aria-label',PANEL_TITLES[panelCurrent?.name]||'Pannello');dl.dataset.panel=panelCurrent?.name||'';if(!ov.dataset.open){ov.dataset.open='1';lastFocus=document.activeElement}dl.setAttribute('tabindex','-1');dl.focus({preventScroll:true})}catch(e){}}
function closeA11y(){try{let ov=$('overlay');ov.dataset.open='';if(lastFocus&&lastFocus.focus&&document.contains(lastFocus)){lastFocus.focus({preventScroll:true})}lastFocus=null}catch(e){}}
function towerStats(type,level){let d=DEFENSES[type],per=type==='mortar'?13:(type==='pentagon'||type==='star')?7:9;return{damage:d.damage?Math.round(d.damage+(level-1)*per):0,range:(d.range||0)+(level-1)*15}}
function upgradePreview(t){if(t.level!==1||!DEFENSES[t.type]||t.type==='lab')return '';let a=towerStats(t.type,1),b=towerStats(t.type,2),parts=[];if(a.damage)parts.push('Danno '+a.damage+' → '+b.damage);if(a.range)parts.push('Gittata '+a.range+' → '+b.range);if(a.damage)parts.push('Cadenza +20%');return parts.length?`<p class="upgrade-preview">${parts.join(' · ')}</p>`:''}
function forecastRoster(){let counts={};plannedTypes(wave+1).forEach(t=>counts[t]=(counts[t]||0)+1);return Object.entries(counts).map(([t,n])=>{let e=ENEMIES[t],narrow=t==='fast',boss=['boss','roller','setSquare'].includes(t);return `<div class="roster-item${boss?' boss':''}"><span class="roster-eraser" style="background:${e.color};${narrow?'width:16px;height:28px':''}"></span><span><b>×${n} ${e.name}</b><small>${e.desc}</small></span></div>`}).join('')}
const LAB_ORDER=['mortar','circles','stitch','sniper','patch','mender','star','spiral','pentagon','octagon'];
const LAB_CHIPS=[['research','discoveries','Scoperte'],['research','projects','Progetti'],['research','studies','Studi'],['charges',null,'Cariche'],['maintenance','paper','Foglio'],['maintenance','defenses','Difese']];

const TARGET_MODES=[['first','Più avanzato'],['strong','Più forte'],['weak','Più debole']],WET_KINDS=['mortar','sniper','pentagon'];
function targetOrder(t){let p=t.priority;return p==='strong'?(a,b)=>b.hp-a.hp:p==='weak'?(a,b)=>a.hp-b.hp:(a,b)=>(a.pathLeft??a.r)-(b.pathLeft??b.r)}
function cycleTarget(i,quiet){let t=towers[i];if(!t?.type)return;let k=TARGET_MODES.findIndex(m=>m[0]===(t.priority||'first'));t.priority=TARGET_MODES[(k+1)%TARGET_MODES.length][0];saveRun();if(!quiet)towerDetails()}
function targetButton(i){let t=towers[i];if(!t||!['triangle','mortar','sniper','pentagon'].includes(t.type))return '';let m=TARGET_MODES.find(m=>m[0]===(t.priority||'first'))||TARGET_MODES[0];return `<button class="set-row" onclick="cycleTarget(${i})"><span><b>Mira: ${m[1]}</b><small>Tocca per cambiare la priorità del bersaglio.</small></span><span class="set-go">⟳</span></button>`}
function starsFor(lost){return lost<=.01?3:lost<=15?2:1}
function recordStars(w,n){if(demo||tut)return;let mode=gameMode==='daily'?'daily':'campaign';if(!meta.stars||typeof meta.stars!=='object')meta.stars={};if(!meta.stars[mode]||typeof meta.stars[mode]!=='object')meta.stars[mode]={};if((meta.stars[mode][w]||0)<n){meta.stars[mode][w]=n;persistMeta()}}
function starTotal(mode){let o=meta.stars?.[mode];return o&&typeof o==='object'?Object.values(o).reduce((a,v)=>a+(v>=1&&v<=3?v:0),0):0}
function show(html,fixed=''){if(pendingAlly){pendingAlly=null;dock()}if(inputMode==='draw')cancelCircle();paused=true;resetContacts();gesture=null;$('overlay').style.display='flex';$('app').classList.add('sheet-open');let chrome=panelCurrent&&panelCurrent.name!=='intro'?`<div class="panel-grip" aria-label="${tr('Trascina verso il basso per chiudere')}"></div><div class="panel-nav"><button class="nav-back" ${panelHistory.length?'onclick="backPanel()" aria-label="Torna al pannello precedente"':'disabled aria-hidden="true" tabindex="-1"'}>‹</button><button class="nav-home" aria-label="Torna alla home" onclick="goHome()"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 11 12 4l8 7"/><path d="M6 10v9h12v-9"/><path d="M10 19v-5h4v5"/></svg></button><span class="panel-title">${PANEL_TITLES[panelCurrent.name]||''}</span><button class="nav-close" aria-label="${started&&!over?'Riprendi la partita':'Chiudi'}" onclick="closePanel()">×</button></div>`:'';$('dialog').innerHTML=chrome+(fixed?'<div class="panel-fixed">'+fixed+'</div>':'')+'<div class="panel-body">'+html+'</div>';$('overlay').scrollTop=0;openA11y()}
function hide(){try{MUSIC.cancelJingle()}catch(_){}closeA11y();$('overlay').style.display='none';$('app').classList.remove('sheet-open');paused=false;last=performance.now();panelCurrent=null;panelHistory=[];panelRestoring=false;resize()}

function readSavedRun(){try{let s=JSON.parse(localStorage.getItem('ultimo-tratto-run-v2')||'null');if(!s||s.version!==2||!['build','wave'].includes(s.phase)||!Array.isArray(s.barriers)||s.barriers.length<1||s.barriers.length>3||!Array.isArray(s.towers)||s.towers.length!==s.barriers.length*8)return null;if(!s.barriers.every((b,i)=>b.r===R+i*80&&Array.isArray(b.hp)&&b.hp.length===N&&b.hp.every(v=>Number.isFinite(v)&&v>=0&&v<=100))||!s.towers.every(t=>(t.type===null||Object.hasOwn(DEFENSES,t.type))&&Number.isInteger(t.level)&&t.level>=1&&t.level<=3)||!Number.isFinite(s.core)||s.core<=0||s.core>100||!Number.isFinite(s.ink)||s.ink<0||s.ink>MAXINK||!Number.isInteger(s.wave)||s.wave<0||s.wave>999)return null;return s}catch(e){return null}}
function saveRun(){if(demo||tut)return;towers.forEach(ensureTowerHealth);if(gameMode==='paths')return;if(!started||over||!['build','wave'].includes(phase)||inputMode==='draw')return;try{let s={version:2,phase,paperKind,paperWear,paperProtection,mode:gameMode,runDay,avatarId,reverseTier,reverseRage,reverseCooldown,reverseElapsed,reverseGoal,fortressInk,tech,researchJob,studies,powerCharges,barriers,towers,patches,stitches,enemies:enemies.filter(e=>!e.dead).slice(0,100),bullets:[],queue,wave,ink,core,score,kills,clock,spawnTimer,nextId,regen,damageMult,repairMult,buildDiscount,circleDiscount,rangeBonus,pulseCooldown,playerLevel,playerXP,selectedPower,powerCooldowns,sealTime,stasisTime,stormTime,bossKills,perkHistory,endless,waveStartCore,perfectWaves,runStats};localStorage.setItem('ultimo-tratto-run-v2',JSON.stringify(s))}catch(e){}}
function restoreRun(){let s=readSavedRun();if(!s){toast('Nessuna partita salvata disponibile');return}init();started=true;over=false;recorded=false;phase=s.phase;paperKind=Object.hasOwn(PAPERS,s.paperKind)?s.paperKind:'grid';paperWear=Number.isFinite(s.paperWear)?Math.max(0,Math.min(1,s.paperWear)):0;paperProtection=Number.isFinite(s.paperProtection)?Math.max(0,Math.min(60,s.paperProtection)):0;paperWarmth=paperAgeValue();avatarId=Number.isInteger(s.avatarId)?s.avatarId:0;reverseTier=Number.isInteger(s.reverseTier)?s.reverseTier:1;reverseRage=Math.max(0,s.reverseRage||0);reverseCooldown=Math.max(0,s.reverseCooldown||0);reverseElapsed=s.reverseElapsed||0;reverseGoal=s.reverseGoal||35;fortressInk=s.fortressInk||160;avatarTarget=null;gameMode=['daily','erasers'].includes(s.mode)?s.mode:'campaign';runDay=typeof s.runDay==='string'?s.runDay:todayKey();barriers=s.barriers;wall=barriers[0].hp;towers=s.towers;for(let t of towers)if(!['first','strong','weak'].includes(t.priority))t.priority='first';let clearedOld=[];towers.forEach((t,i)=>{ensureTowerHealth(t);if(t.type&&t.destroyed){clearedOld.push(i);clearTower(t)}});tech={triangle:true,...(s.tech||{})};if(!s.tech)for(let t of towers)if(t.type&&t.type!=='lab')tech[t.type]=true;researchJob=validJob(s.researchJob)?s.researchJob:null;if(researchJob?.kind==='branch'&&clearedOld.includes(researchJob.tower))researchJob=null;for(let k of Object.keys(studies))studies[k]=Math.max(0,Math.floor(s.studies?.[k]||0));for(let key of Object.keys(powerCharges))powerCharges[key]=Math.max(0,Math.min(3,Math.floor(s.powerCharges?.[key]||0)));for(let t of towers)if(t.type&&t.level===3&&SPECIALIZATIONS[t.type]&&!SPECIALIZATIONS[t.type]?.[t.branch])t.branch=Object.keys(SPECIALIZATIONS[t.type])[0];patches=(s.patches||[]).filter(p=>Number.isFinite(p.shield)&&Number.isFinite(p.life)&&barriers[p.barrier]);stitches=(s.stitches||[]).filter(p=>Number.isFinite(p.life)&&barriers[p.barrier]&&Array.isArray(p.indices));enemies=(s.enemies||[]).filter(e=>Object.hasOwn(ENEMIES,e.type)&&Number.isFinite(e.r)&&Number.isFinite(e.a)&&Number.isFinite(e.hp)).slice(0,100);queue=(s.queue||[]).filter(e=>Object.hasOwn(ENEMIES,e.type)&&Number.isFinite(e.a));for(let k of ['wave','ink','core','score','kills','clock','spawnTimer','nextId','regen','damageMult','repairMult','buildDiscount','circleDiscount','rangeBonus','pulseCooldown','waveStartCore','perfectWaves'])if(!Number.isFinite(s[k])){toast('Salvataggio incompleto');started=false;intro();return}wave=s.wave;ink=s.ink;core=s.core;score=s.score;kills=s.kills;clock=s.clock;spawnTimer=s.spawnTimer;nextId=s.nextId;regen=s.regen;damageMult=s.damageMult;repairMult=s.repairMult;buildDiscount=s.buildDiscount;circleDiscount=s.circleDiscount;rangeBonus=s.rangeBonus;pulseCooldown=s.pulseCooldown;playerLevel=Number.isInteger(s.playerLevel)?Math.max(1,Math.min(20,s.playerLevel)):Math.min(7,1+Math.floor(s.wave*.75));playerXP=Number.isFinite(s.playerXP)?Math.max(0,s.playerXP):0;selectedPower=Object.hasOwn(POWERS,s.selectedPower)&&POWERS[s.selectedPower].level<=playerLevel?s.selectedPower:'pulse';for(let key of Object.keys(powerCooldowns))powerCooldowns[key]=Math.max(0,Math.min(60,Number(s.powerCooldowns?.[key])||0));sealTime=Math.max(0,Math.min(7.5,s.sealTime||0));stasisTime=Math.max(0,Math.min(3,s.stasisTime||0));stormTime=Math.max(0,Math.min(2.2,s.stormTime||0));bossKills=Number.isInteger(s.bossKills)?s.bossKills:0;waveStartCore=s.waveStartCore;perfectWaves=s.perfectWaves;perkHistory=(s.perkHistory||[]).filter(k=>Object.hasOwn(PERKS,k));endless=!!s.endless;runStats=s.runStats||{seconds:0,repairs:0,pulses:0};selected=-1;inputMode='repair';resetContacts();camera.zoom=1;camera.panX=camera.panY=0;hide();dock();resize();ui();toast('Bentornato. Il quaderno ti aspettava.')}

function intro(){demoStart();visitPanel('intro',[]);let saved=readSavedRun();show(`<header class="home-head"><button class="home-side" aria-label="Crediti" onclick="credits()">${ICO.info}</button><h1><span>Confused</span><span class="pen">Sketch.</span></h1><button class="home-side" aria-label="Come si gioca" onclick="guide()">${ICO.help}</button></header><nav class="home-dock" aria-label="Menu principale"><div class="demo-cap" id="demoCap" aria-hidden="true"></div>${saved?`<button class="cta alt resume" onclick="restoreRun()"><b>Riprendi</b><small>${t('quaderno salvato · ondata {0}',saved.wave||1)}</small></button>`:''}<div class="modes"><button class="cta" onclick="startGame('campaign')"><b>Quaderno</b><small>difendi il cerchio</small></button><button class="cta blue" onclick="mapMenu()"><b>Percorsi</b><small>mappe e difese</small></button></div><div class="ibar"><button class="ib" onclick="startGame('daily')">${ICO.cal}<b>Sfida</b></button><button class="ib" onclick="notebook()">${ICO.trophy}<b>Traguardi</b></button><button class="ib" onclick="gommario()">${ICO.book}<b>Gommario</b></button><button class="ib" onclick="settingsMenu(false)">${ICO.settings}<b>Opzioni</b></button></div></nav>`);resize()}
function startGame(mode=gameMode,material=null){if(mode==='paths'){mapMenu();return}if(mode==='campaign'&&!material){choosePaper();return}if(mode==='erasers'){startReverse(1);return}gameMode=mode;runDay=todayKey();init();paperKind=gameMode==='daily'?Object.keys(PAPERS)[[...runDay].reduce((n,c)=>n+c.charCodeAt(0),0)%4]:(Object.hasOwn(PAPERS,material)?material:'grid');recorded=false;autosaveTimer=0;runStats={seconds:0,repairs:0,pulses:0};meta.starts++;statAdd('paper_'+paperKind);let day=todayKey();if(!meta.days.includes(day))meta.days.push(day);meta.days=meta.days.slice(-180);persistMeta();if(gameMode==='daily')ink=140;inputMode='repair';resetContacts();camera.zoom=1;camera.panX=camera.panY=0;resize();started=true;hide();toast('Costruisci il Laboratorio (45✎) su un +.');sfx('start')}
function guide(){if(gameMode==='erasers'){reverseGuide();return}if(gameMode==='paths'){pathGuide();return}visitPanel('guide',[]);show(`<div class="eyebrow">COME SI GIOCA</div><h2>Cinque regole.</h2><button class="btn green" onclick="startTutorial()">Prova il tutorial interattivo</button><ol class="guide"><li><b>Ripara il cerchio.</b> Trascina sul contorno per ripassare le brecce. Paghi solo i tratti danneggiati.</li><li><b>Parti dal Laboratorio.</b> Costruiscilo su una postazione + (45✎). Sblocca ricerche, potenziamenti e cariche.</li><li><b>Costruisci e potenzia.</b> Tocca un + per una difesa. Al livello 2 e 3 puoi scegliere un’evoluzione.</li><li><b>Usa i poteri.</b> Soffio, Sigillo, Stasi e Tempesta si caricano nel Laboratorio e si usano durante gli assalti.</li><li><b>Ferma i boss.</b> Il Rullo segnala la sua corsia, La Squadra perde la corazza dopo il primo taglio, la Cancellatrice va eliminata per chiudere l’ondata.</li></ol>`)}
function openMenu(){if(!started||over){showMenu(false);return}showMenu(true)}
function showMenu(active){visitPanel('menu',[active]);show(`<div class="eyebrow">MENU</div><h2>${active?'Pausa':'Confused Sketch'}</h2><p>${active?'Ondata '+wave+' · '+score+' punti · livello '+playerLevel+' ('+playerXP+'/'+xpThreshold()+' XP)':'Una piccola difesa contro la cancellazione.'}</p><button class="btn green" onclick="${active?'resume()':'intro()'}">${active?'▷ Riprendi la partita':'Torna al gioco'}</button>${active&&phase==='build'&&gameMode!=='paths'?'<button class="btn light" onclick="resume();autoRepair()">◌ Ripassa tutti i cerchi · 35✎</button>':''}${started&&!over||active?`<button class="btn light" onclick="labAccess()">${gameMode==='erasers'?'▱ Compra rinforzi':'⌂ Laboratorio'}</button>`:''}<div class="menu-grid"><button class="btn light" onclick="gommario()">▱ Gommario</button><button class="btn light" onclick="notebook()">✓ Traguardi</button></div><button class="btn light" onclick="settingsMenu(${active})">${ICO.settings}Impostazioni</button>${active?'<button class="btn light warning-action" onclick="confirmRestart()">Nuovo foglio</button>':''}`)}
