const SETTINGS_TABS=[['audio','audio','Audio'],['game','pencil','Gioco'],['access','look','Aspetto'],['info','info','Info']];
let settingsTab='audio';
function settingsTabKey(e,id){const i=SETTINGS_TABS.findIndex(x=>x[0]===id);let n=i;if(e.key==='ArrowRight')n=(i+1)%SETTINGS_TABS.length;else if(e.key==='ArrowLeft')n=(i+SETTINGS_TABS.length-1)%SETTINGS_TABS.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=SETTINGS_TABS.length-1;else return;e.preventDefault();settingsTab=SETTINGS_TABS[n][0];settingsMenu(activePanelGame());document.getElementById('settings-tab-'+settingsTab)?.focus()}
function settingsTabs(){return `<div class="lab-tabs set-tabs" role="tablist">${SETTINGS_TABS.map(([id,ico,name])=>`<button role="tab" id="settings-tab-${id}" aria-controls="settings-pane-${id}" tabindex="${id===settingsTab?0:-1}" onkeydown="settingsTabKey(event,'${id}')" aria-selected="${id===settingsTab}" class="${id===settingsTab?'active':''}" onclick="settingsTab='${id}';settingsMenu(activePanelGame())">${ICO[ico]}<span>${name}</span></button>`).join('')}</div>`}
function settingsSection(id,icon,title,hint,body){return id===settingsTab?`<div class="set-group" id="settings-pane-${id}" role="tabpanel" aria-labelledby="settings-tab-${id}">${body}</div>`:''}
function volRow(key,label,on,preview){return `<label class="set-row"><span><b>${label}</b></span><input type="range" min="0" max="100" step="5" value="${prefs[key]}" ${on?'':'disabled'} aria-label="${label}" oninput="setPref('${key}',+this.value,true);this.nextElementSibling.textContent=this.value" ${preview?'onchange="sfx(\'build\')"':''}><output>${prefs[key]}</output></label>`}
function settingsMenu(active=activePanelGame()){visitPanel('settings',[active]);show(`${prefsOk?'':'<p class="warning">Questo browser non permette di salvare le impostazioni.</p>'}${settingsTabs()}${settingsSection('audio','','','',`${prefSwitch('music','Musica','Brani di sottofondo per home, preparazione e ondate.')}${volRow('musicVol','Volume musica',prefs.music)}${prefSwitch('sound','Effetti sonori','Matite, colpi e gommate.')}${volRow('volume','Volume effetti',prefs.sound,true)}${hapticAvailable()?prefSwitch('haptic','Vibrazione','Un breve impulso per costruzioni e brecce.'):''}`)}${settingsSection('game','','','',`${GC.available()?prefSwitch('gc','Game Center','Invia traguardi e classifiche a Game Center.'):''}${prefSeg('gfx','Grafica',[['classic','Classica'],['25d','2.5D']])}${G25()?prefSeg('fx','Particelle',[['gl','Avanzate'],['std','Standard']]):''}<details class="set-help"><summary>Dettagli grafici</summary><p class="panel-note">2.5D aggiunge prospettiva, volumi ed effetti più ricchi. Se il gioco rallenta, scegli Classica. Le particelle avanzate disegnano polvere di grafite e urti sulla GPU.</p></details>`)}${settingsSection('access','','','',`<button class="set-row" onclick="languageMenu()"><span><b>Lingua</b><small translate="no">${langName()}</small></span><span class="set-go">›</span></button>${prefSeg('motion','Movimento ridotto',[['auto','Auto'],['on','Sì'],['off','No']])}<button class="set-row" role="switch" aria-checked="${prefs.textScale>1}" onclick="setPref('textScale',${prefs.textScale>1?1:1.15})"><span><b>Testo grande</b><small>Ingrandisce i pannelli del 15%.</small></span><span class="switch ${prefs.textScale>1?'on':''}" aria-hidden="true"><i></i></span></button>${prefSwitch('contrast','Contrasto alto','Testi più scuri e bordi più marcati.')}`)}${settingsSection('info','','','',`<button class="set-row" onclick="credits()"><span><b>Crediti e licenze</b><small>Musiche, caratteri, suoni e strumenti usati.</small></span><span class="set-go">›</span></button><button class="set-row" onclick="guide()"><span><b>Come si gioca</b><small>Le regole essenziali in cinque punti.</small></span><span class="set-go">›</span></button><button class="set-row danger" onclick="confirmReset()"><span><b>Cancella i dati di questo dispositivo</b><small>Partite salvate, traguardi e impostazioni.</small></span></button>`)}`)}
