function reverseUI(){$('hint').textContent=pendingAlly?'Tocca la fascia rosa · poi conferma Schiera':'Tocca per muovere TU · Schiera gomme per i rinforzi';$('footer').textContent='Obiettivo: cancella '+reverseGoal+'% · proteggi la gomma TU';$('paperStatus').hidden=true;$('inkLabel').textContent='BRICIOLE';$('coreLabel').textContent='LA TUA GOMMA';$('coreBar').style.background='#b87583';$('ink').textContent=Math.floor(ink);$('regen').textContent=' +5/s';$('core').innerHTML=Math.ceil(core)+'<small>%</small>';$('coreBar').style.width=core+'%';$('inkBar').style.width=ink/MAXINK*100+'%';$('playerLevel').textContent=playerLevel;$('xpValue').textContent=' '+playerXP+'/'+xpThreshold();$('xpBar').style.width=playerXP/xpThreshold()*100+'%';$('score').textContent=score;$('bossHud').hidden=true;$('app').classList.remove('boss-active');$('phase').innerHTML='<i class="dot"></i>'+(gestureLocked?'INQUADRATURA · PAUSA':'SGOMMA · FORTEZZA '+reverseTier);$('integrity').textContent='CANCELLATO '+Math.floor(reverseProgress())+' / '+reverseGoal+'%';if($('rageButton')){$('rageButton').textContent=reverseRage>0?'Furia attiva':reverseCooldown>0?'Furia · '+Math.ceil(reverseCooldown)+'s':'Furia · 15';$('rageButton').disabled=over||paused||reverseCooldown>0||ink<15||reverseRage>0}}

