function upgradeFx(i){let p=slot(i),t=towers[i];t.flash=1;burst(p.x,p.y,DEFENSES[t.type].color,18);addFx('seal',{x:p.x,y:p.y,radius:40,color:DEFENSES[t.type].color,life:.8})}
function mixInk(a,b,k){let x=parseInt(a.slice(1),16),y=parseInt(b.slice(1),16);return '#'+[16,8,0].map(q=>Math.round(((x>>q)&255)*(1-k)+((y>>q)&255)*k).toString(16).padStart(2,'0')).join('')}
function defensePalette(t){let base=DEFENSES[t.type]?.color||'#889988',c=mixInk(base,'#fff5e5',t.level===1?.38:t.level===2?.14:.02);return {light:'#fff9ec',mid:c,dark:mixInk(base,'#30483f',.45),rim:t.level===3?'#bd9d60':mixInk(base,'#fff7df',.5)}}
function shapePoints(type,r){let n={triangle:3,mortar:6,sniper:4,mender:4,pentagon:5,octagon:8}[type];if(type==='star')return Array.from({length:10},(_,i)=>[Math.cos(i*Math.PI/5-Math.PI/2)*(i%2?r*.48:r),Math.sin(i*Math.PI/5-Math.PI/2)*(i%2?r*.48:r)]);if(!n)return null;return Array.from({length:n},(_,i)=>{let a=i*TAU/n+(type==='triangle'?0:type==='mender'?Math.PI/4:type==='mortar'?-Math.PI/3:type==='octagon'?-Math.PI/2+Math.PI/8:-Math.PI/2);return [Math.cos(a)*r*(type==='sniper'?1.22:1),Math.sin(a)*r*(type==='sniper'?.72:1)]})}
