  cluster:()=>{dot(0,-3,1.8);dot(-3.2,2.4,1.8);dot(3.2,2.4,1.8)},sticky:()=>{dot(0,1,3.6);L(0,-6,-2.2,-2,2.2,-2,0,-6)},
  chain:()=>{L(-5,3,-1,-3,1,3,5,-3)},hunter:()=>{ctx.beginPath();ctx.arc(0,0,3.8,0,TAU);ctx.stroke();L(-6.5,0,-2.5,0);L(2.5,0,6.5,0);L(0,-6.5,0,-2.5);L(0,2.5,0,6.5)},
