function drawCompass(p,r){ctx.save();ctx.strokeStyle='#698d7b66';ctx.lineWidth=1;ctx.setLineDash([]);ctx.beginPath();for(let j=0;j<48;j++){let a=j*TAU/48,len=j%4===0?9:4;ctx.moveTo(p.x+Math.cos(a)*(r-len),p.y+Math.sin(a)*(r-len));ctx.lineTo(p.x+Math.cos(a)*r,p.y+Math.sin(a)*r)}ctx.stroke();ctx.beginPath();ctx.moveTo(p.x-5,p.y);ctx.lineTo(p.x+5,p.y);ctx.moveTo(p.x,p.y-5);ctx.lineTo(p.x,p.y+5);ctx.stroke();ctx.restore()}
