function updatePaperWear(dt){if(phase!=='wave'||paused||over||!started||gestureLocked||gameMode==='erasers')return;let unprotected=Math.max(0,dt-paperProtection);paperProtection=Math.max(0,paperProtection-dt);paperWear=Math.min(1,paperWear+unprotected*(.0015+Math.min(12,wave)*.0002))}
