function choosePaper(){visitPanel('paper',[]);show(`<div class="eyebrow">NUOVA PARTITA · 8 ONDATE</div><h2>Scegli il foglio.</h2>${meta.tutDone?'':'<button class="btn green" onclick="startTutorial()">Prima volta? Prova il tutorial</button>'}<p>Quattro stili di gioco, stessa difficoltà delle ondate. L’usura riduce la rigenerazione: curala nel Laboratorio.</p><div class="catalogue">${Object.entries(PAPERS).filter(([k,p])=>!p.paths).map(([k,p])=>`<button class="choice" style="background:${p.color}" onclick="startGame('campaign','${k}')"><span class="paper-swatch ${k}" aria-hidden="true"></span><b>${p.icon} ${p.name}</b><small>${p.desc}</small></button>`).join('')}</div>`)}
function paperCareContent(busy){return `<div class="research-status"><b>${paperProfile().name} · usura ${Math.round(paperWear*100)}%</b><span>Rigenerazione ${effectiveRegen().toFixed(2)}✎/s · penalità −${Math.round(paperWear*40)}%</span><progress aria-label="Usura del foglio" max="1" value="${paperWear}"></progress><small>${paperProtection>0?'Protetto per altri '+Math.ceil(paperProtection)+'s d’assalto.':'Le cure occupano il banco e si applicano al completamento.'}</small></div>${Object.entries(PAPER_CURES).map(([key,c])=>labCard({name:c.name,desc:c.desc,cost:c.cost,time:c.time,action:`startPaperCure('${key}')`,reason:c.restore>0&&paperWear<=0?'Foglio già sano':!c.restore&&paperProtection>0?'Protezione già attiva':blockReason(c.cost)})).join('')}`}
function startPaperCure(key){let c=PAPER_CURES[key];if(!c||gameMode==='erasers'||(c.restore>0?paperWear<=0:paperProtection>0))return false;return beginJob({kind:'care',key},c.cost,c.time)}
function showAppearance(active=started&&!over){visitPanel('appearance',[active]);show(`<div class="eyebrow">STATO DEL FOGLIO</div><h2>La carta vive.</h2><p>${paperProfile().name} · usura ${Math.round(paperWear*100)}%.<br>${paperProfile().desc}</p><p>Durante gli assalti la carta ingiallisce e rigenera meno grafite, fino a −40%. Il colore cambia gradualmente; le cure del Laboratorio lo riportano verso il colore originale del materiale.</p>${active&&gameMode!=='erasers'?`<button class="btn green" onclick="labMenu('care')">${hasLab()?'Apri le cure del Laboratorio':'Costruisci un Laboratorio per curare il foglio'}</button>`:''}<p>La Sfida del giorno assegna lo stesso materiale a tutti. In Sgomma usura e materiali sono disattivati.</p><button class="btn light" onclick="showMenu(${active})">Torna al menu</button>`)}
