function viewFocus(){let fx=camera.fx??CX,fy=camera.fy??CY;return{x:fx,y:CY+(fy-CY)*TL(),wy:fy}}
function applyView(){view.scale=camera.base*camera.zoom;let f=viewFocus();view.x=camera.cx-f.x*view.scale+camera.panX;view.y=camera.cy-f.y*view.scale+camera.panY}
function zoomMin(){return gameMode==='paths'?.36:.55}
function clampPan(){if(gameMode==='paths'&&curMap()?.bounds){let b=curMap().bounds,f=viewFocus(),sc=camera.base*camera.zoom,tl=TL();camera.panX=Math.max((f.x-b.x1)*sc,Math.min((f.x-b.x0)*sc,camera.panX));camera.panY=Math.max(-(b.y1-f.wy)*tl*sc,Math.min(-(b.y0-f.wy)*tl*sc,camera.panY))}else{camera.panX=Math.max(-W,Math.min(W,camera.panX));camera.panY=Math.max(-H,Math.min(H,camera.panY))}}
function fitView(){camera.zoom=1;camera.panX=camera.panY=0;applyView()}
function screenPoint(e){let r=cv.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function resetContacts(){avatarTarget=null;contacts.clear();pointers.clear();transformState=null;gestureLocked=false;drawPointer=null;drawPath=[];$('gestureHint').classList.remove('visible')}
function beginTransform(){let a=[...contacts.values()];if(a.length<2)return;let p=a[0].screen,q=a[1].screen,mid={x:(p.x+q.x)/2,y:(p.y+q.y)/2};transformState={distance:Math.max(1,dist(p,q)),zoom:camera.zoom,anchor:{x:(mid.x-view.x)/view.scale,y:(mid.y-view.y)/view.scale}};gestureLocked=true;avatarTarget=null;pointers.clear();drawPath=[];drawPointer=null;$('gestureHint').textContent='Due dita · sposta e ingrandisci';$('gestureHint').classList.add('visible')}
function moveTransform(){if(!transformState||contacts.size<2)return;let a=[...contacts.values()],p=a[0].screen,q=a[1].screen,mid={x:(p.x+q.x)/2,y:(p.y+q.y)/2};camera.zoom=Math.max(zoomMin(),Math.min(2.2,transformState.zoom*dist(p,q)/transformState.distance));let scale=camera.base*camera.zoom,f=viewFocus();camera.panX=mid.x-camera.cx+(f.x-transformState.anchor.x)*scale;camera.panY=mid.y-camera.cy+(f.y-transformState.anchor.y)*scale;clampPan();applyView()}
function openRepairTools(){visitPanel('tools',[]);show(`<div class="eyebrow">LA TUA MATITA</div><h2>Come ripari?</h2><div class="repair-options">${Object.entries(REPAIR_TOOLS).map(([k,t])=>`<button class="choice ${repairTool===k?'selected':''}" onclick="selectRepairTool('${k}')"><b>${t.icon} ${t.name}</b><small>${k!=='pencil'&&!tech[k]?'⌁ Richiedi questa ricerca al Laboratorio. ':''}${t.desc}</small></button>`).join('')}</div>`)}
function selectRepairTool(tool){if(!REPAIR_TOOLS[tool])return;if(tool!=='pencil'&&!tech[tool]){labMenu('research');return}repairTool=tool;hide();dock();toast(REPAIR_TOOLS[tool].desc)}
function nearestBarrier(p){let radius=Math.hypot(p.x-CX,p.y-CY);return barriers.reduce((a,b)=>Math.abs(b.r-radius)<Math.abs(a.r-radius)?b:a,barriers[0])}
function useRepairTool(start,end=start){if(repairTool!=='pencil'&&!tech[repairTool]){toast('Prima completa la ricerca.');return false}let b=nearestBarrier(end);if(!b||Math.abs(Math.hypot(end.x-CX,end.y-CY)-b.r)>Math.max(30,20/view.scale)){toast('Agisci sul contorno di un cerchio.');return false}let center=index(Math.atan2(end.y-CY,end.x-CX));if(repairTool==='patch'){if(ink<12){toast('Servono 12✎ per la toppa.');return false}if(patches.some(p=>p.barrier===b.id&&Math.abs(Math.atan2(Math.sin((p.center-center)*TAU/N),Math.cos((p.center-center)*TAU/N)))<.15)){toast('Questo tratto ha già una toppa.');return false}ink-=12;patches.push({barrier:b.id,center,width:4,shield:140,life:10*paperProfile().duration});burst(CX+Math.cos(center/N*TAU)*b.r,CY+Math.sin(center/N*TAU)*b.r,'#b4c7a5',10);toast('Toppa applicata · '+(10*paperProfile().duration)+' secondi');sfx('repair');ui();return true}if(repairTool==='stitch'){let begin=index(Math.atan2(start.y-CY,start.x-CX)),delta=((center-begin+N*1.5)%N)-N/2,indices=[];if(Math.abs(delta)>14){toast('Cuci una breccia più corta.');return false}if(Math.abs(delta)<2){for(let j=-3;j<=3;j++)indices.push((center+j+N)%N)}else{let direction=Math.sign(delta);for(let j=0;j<=Math.abs(delta);j++)indices.push((begin+j*direction+N)%N)}let dir=indices.length>1&&((indices[1]-indices[0]+N)%N)===1?1:-1,before=(indices[0]-dir+N)%N,after=(indices.at(-1)+dir+N)%N;if(!indices.some(i=>b.hp[i]<20)||b.hp[before]<20||b.hp[after]<20){toast('Serve una breccia con due estremità sane.');return false}if(ink<8){toast('Servono 8✎ per la cucitura.');return false}ink-=8;for(let i of indices)b.hp[i]=Math.max(65,b.hp[i]);stitches.push({barrier:b.id,indices,life:8});toast('Breccia ricucita.');sfx('repair');ui();return true}return false}
