/* ===== Tutorial interattivo: gira sul motore vero (Quaderno, foglio a quadretti), non salva e la scintilla non muore ===== */
let tut=null;
const TUT=[
{t:'Questo è il tuo foglio',d:'Il cerchio di matita è la tua difesa. Al centro c’è la scintilla: se la sua vita arriva a zero hai perso.',next:1},
{t:'Costruisci una difesa',d:'Tocca una postazione vuota, quella con il +.',hl:2,done:()=>selected===2||!!towers[2].type},
{t:'Scegli il Triangolo',d:'Dall’elenco tocca il Triangolo: spara da solo alle gomme vicine.',hl:2,done:()=>!!towers[2].type},
{t:'Fai partire l’ondata',d:'Premi Inizia in basso. Le difese sparano da sole.',done:()=>phase==='wave'},
{t:'Guarda le difese lavorare',d:'Le gomme mordono il contorno. Aspetta la fine dell’ondata.',done:()=>phase==='build'&&wave>=1},
{t:'Ripassa il contorno',d:'Si è aperta una breccia. Trascina il dito sul tratto evidenziato per ripararlo con la grafite.',arc:[0,16],enter:()=>{ink=Math.max(ink,120);for(let i=0;i<16;i++)barriers[0].hp[i]=18},done:()=>{let a=0;for(let i=0;i<16;i++)a+=barriers[0].hp[i];return a/16>=60}},
{t:'Il Laboratorio',d:'Costruisci il Laboratorio (45✎) su un +: sblocca nuove difese, ricerche e poteri. Ora puoi provare da solo.',next:1},
{t:'Pronta a giocare',d:'Hai visto le basi: difendi, ripara, ricerca. I poteri e i cerchi esterni li scoprirai giocando.',end:1}
];
function startTutorial(){if(started&&!over&&!tut)saveRun();gameMode='campaign';runDay=todayKey();init();paperKind='grid';recorded=true;autosaveTimer=0;runStats={seconds:0,repairs:0,pulses:0};inputMode='repair';resetContacts();camera.zoom=1;camera.panX=camera.panY=0;ink=200;tut={i:0,t:0};resize();started=true;hide();tutShow();sfx('start')}
function tutShow(){let el=$('coach');if(!tut||!el)return;let s=TUT[tut.i];el.hidden=false;el.innerHTML=`<div class="cs">${tr('Tutorial')} · ${tut.i+1}/${TUT.length}</div><b>${tr(s.t)}</b><p>${tr(s.d)}</p><div class="cb">${s.end?'':`<button class="skip" onclick="tutEnd()">${tr('Salta')}</button>`}${s.next?`<button class="go" onclick="tutGo(${tut.i+1})">${tr('Avanti')}</button>`:''}${s.end?`<button class="go" onclick="tutEnd(true)">${tr('Fine')}</button>`:''}</div>`}
function tutGo(i){if(!tut)return;tut.i=Math.min(TUT.length-1,i);let s=TUT[tut.i];if(s.enter)s.enter();tutShow();sfx('build')}
function tutEnd(done){if(!tut)return;tut=null;let el=$('coach');if(el)el.hidden=true;if(done){meta.tutDone=1;persistMeta()}started=false;over=false;paused=false;init();phase='intro';ui();intro()}
function tutTick(){if(!tut||!started)return;core=100;over=false;let s=TUT[tut.i];if(s.done&&s.done())tutGo(tut.i+1);let el=$('coach');if(el){el.style.display=paused&&panelCurrent&&panelCurrent.name==='menu'?'none':'';el.classList.toggle('low',$('overlay').style.display!=='none')}}
function drawTutHL(){if(!tut)return;let s=TUT[tut.i];if(!s)return;let pu=.5+.5*Math.sin(clock*5);ctx.save();ctx.strokeStyle='#c4574c';ctx.lineWidth=3;ctx.lineCap='round';if(s.hl!=null){let p=slot(s.hl);ctx.setLineDash([7,6]);ctx.lineDashOffset=-clock*14;ctx.beginPath();ctx.arc(p.x,p.y,34+pu*4,0,TAU);ctx.stroke()}if(s.arc){let a0=s.arc[0]/N*TAU,a1=s.arc[1]/N*TAU;ctx.globalAlpha=.55+pu*.4;ctx.lineWidth=9;ctx.beginPath();ctx.arc(CX,CY,R,a0-.03,a1+.03);ctx.stroke()}ctx.restore()}

/* ===== Home animata: una partita dimostrativa gira dietro i pulsanti (non salva, non conta, non suona) ===== */
let demo=null;
function demoStart(){if(demo&&!started&&!over)return;try{started=false;over=false;gameMode='campaign';init();demo={phase:'build',wait:1.2,paperT:0,paperI:0};paperKind='grid';tech={triangle:true,spiral:true,mortar:true,sniper:true,pentagon:true,star:true};ink=999;paused=false;barriers.push({r:R+80,hp:Array(N).fill(100),id:1});for(let k=0;k<8;k++)towers.push({type:null,level:1,cooldown:0,flash:0,angle:-Math.PI/2+k*TAU/8});const plan=['lab','triangle','spiral','mortar','sniper','pentagon','star','triangle','triangle','mortar','spiral','star','triangle','pentagon','sniper','spiral'];towers.forEach((t,i)=>{selected=i;build(plan[i%plan.length])});selected=-1;towers.forEach((t,i)=>{if(t.type&&t.type!=='lab'&&i%2===0)t.level=2});inputMode='repair';phase='build';try{resize()}catch(e){}}catch(e){demo=null}}
