function demoStep(dt){if(!demo||started||demoOverlayOpen()||motionReduced())return;const sv=[started,phase,paused,over,gameSpeed];started=true;over=false;paused=false;phase=demo.phase;gameSpeed=1;try{core=100;for(const b of barriers)for(let q=0;q<N;q++)b.hp[q]=Math.min(100,b.hp[q]+dt*14);demo.paperT+=dt;if(demo.paperT>7){demo.paperT=0;const ks=Object.keys(PAPERS);demo.paperI=(demo.paperI+1)%ks.length;paperKind=ks[demo.paperI]}try{const cap=$('demoCap');if(cap&&cap.dataset&&cap.dataset.k!==paperKind){cap.dataset.k=paperKind;cap.textContent=t('Foglio: {0}',tr(PAPERS[paperKind].name))}}catch(e){}for(const t of towers){if(!t.type)continue;ensureTowerHealth(t);t.hp=t.maxhp;t.destroyed=false}ink=MAXINK;if(phase==='build'){demo.wait-=dt;if(demo.wait<=0){if(wave>=4)wave=0;startWave();demo.wait=2.4}}update(dt);demo.phase=phase}catch(e){demo=null}finally{started=sv[0];phase=sv[1];paused=sv[2];over=sv[3];gameSpeed=sv[4]}}
function frame(t){let dt=Math.max(0,Math.min(.04,(t-last)/1000||0));last=t;if(tut)tutTick();scrapeTick();stepIntro(dt);if(demo&&!started)demoStep(dt);document.body.classList.toggle('home',!started);{let rc=$('recenter');if(rc)rc.hidden=!(started&&!over&&!paused&&!introFly&&(Math.abs(camera.zoom-1)>.03||Math.abs(camera.panX)>10||Math.abs(camera.panY)>10))}update(dt*gameSpeed);GLFX.step(paused?0:dt*gameSpeed);paperWarmth+=(paperAgeValue()-paperWarmth)*(1-Math.exp(-dt*1.8));draw();radialUpdate();requestAnimationFrame(frame)}init();phase='intro';ui();intro();requestAnimationFrame(frame);setTimeout(resize,400);

